import 'dart:io';

import 'package:path/path.dart' as path;
import 'package:serverpod_cli/src/util/android_signing_modifier.dart';
import 'package:test/test.dart';

// Matches the file generated by `flutter create` for Android.
const _generatedBuildFile = '''
plugins {
    id("com.android.application")
    id("dev.flutter.flutter-gradle-plugin")
}

android {
    namespace = "com.example.app"

    buildTypes {
        release {
            // TODO: Add your own signing config for the release build.
            // Signing with the debug keys for now, so `flutter run --release` works.
            signingConfig = signingConfigs.getByName("debug")
        }
    }
}
''';

void main() {
  group('Given a Flutter app with a generated Android build file,', () {
    late Directory dir;
    late File buildFile;

    setUp(() {
      dir = Directory.systemTemp.createTempSync('android_signing_test');
      buildFile =
          File(path.join(dir.path, 'android', 'app', 'build.gradle.kts'))
            ..createSync(recursive: true)
            ..writeAsStringSync(_generatedBuildFile);
    });

    tearDown(() => dir.deleteSync(recursive: true));

    test(
      'when adding the release signing config,'
      'then the signing config reads the Serverpod Cloud environment variables.',
      () async {
        var result = await AndroidSigningModifier.addReleaseSigningConfig(dir);
        var contents = buildFile.readAsStringSync();

        expect(result, isTrue);
        for (var variable in [
          'SERVERPOD_APP_BUILD',
          'ANDROID_KEYSTORE_PATH',
          'ANDROID_KEYSTORE_PASSWORD',
          'ANDROID_KEY_ALIAS',
          'ANDROID_KEY_PASSWORD',
        ]) {
          expect(contents, contains('System.getenv("$variable")'));
        }
        expect(contents, contains('signingConfigs.getByName("release")'));
        expect(contents, contains('signingConfigs.getByName("debug")'));
      },
    );

    test(
      'when the build file has unexpected content,'
      'then it is left untouched.',
      () async {
        buildFile.writeAsStringSync('android {}');

        var result = await AndroidSigningModifier.addReleaseSigningConfig(dir);

        expect(result, isFalse);
        expect(buildFile.readAsStringSync(), 'android {}');
      },
    );
  });

  test(
    'Given no Android build file,'
    'when adding the release signing config,'
    'then it returns false.',
    () async {
      var dir = Directory.systemTemp.createTempSync('android_signing_test');
      addTearDown(() => dir.deleteSync(recursive: true));

      expect(
        await AndroidSigningModifier.addReleaseSigningConfig(dir),
        isFalse,
      );
    },
  );
}
